"""
Offline endpoint-aligned denoising with bounded EMD-style IMF rejection,
transition-aware segmentation, and persistent shape reconstruction.
"""
import numpy as np

try:
    from scipy.signal import savgol_filter
except Exception:
    savgol_filter = None

try:
    from scipy.interpolate import PchipInterpolator
except Exception:
    PchipInterpolator = None


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1 or x.size < window_size:
        raise ValueError("window_size must be positive and not exceed signal length")
    cs = np.concatenate(([0.0], np.cumsum(x)))
    return (cs[window_size:] - cs[:-window_size]) / float(window_size)


def _finite_signal(x):
    if np.all(np.isfinite(x)):
        return x
    good = np.isfinite(x)
    if not np.any(good):
        return np.zeros_like(x)
    ii = np.arange(x.size)
    return np.interp(ii, ii[good], x[good])


def _median3(x):
    if x.size < 3:
        return x.copy()
    p = np.pad(x, (1, 1), mode="edge")
    return np.median(np.stack((p[:-2], p[1:-1], p[2:])), axis=0)


def _sg(x, frame):
    x = np.asarray(x, dtype=float)
    if savgol_filter is None or x.size < 5:
        return x.copy()
    f = min(int(frame), x.size if x.size % 2 else x.size - 1)
    if f < 5:
        return x.copy()
    try:
        y = savgol_filter(x, f, min(3, f - 2), mode="interp")
        return y if np.all(np.isfinite(y)) else x.copy()
    except Exception:
        return x.copy()


def _smooth_piece(piece, requested_frame=21):
    clean = _median3(np.asarray(piece, dtype=float))
    n = clean.size
    if n < 32 or PchipInterpolator is None:
        return _sg(clean, requested_frame)

    def envelope(v, upper):
        if upper:
            pts = np.flatnonzero((v[1:-1] >= v[:-2]) & (v[1:-1] > v[2:])) + 1
        else:
            pts = np.flatnonzero((v[1:-1] <= v[:-2]) & (v[1:-1] < v[2:])) + 1
        pts = np.unique(np.r_[0, pts, v.size - 1])
        if pts.size < 2:
            return None
        try:
            z = PchipInterpolator(pts.astype(float), v[pts])(np.arange(v.size))
            return z if np.all(np.isfinite(z)) else None
        except Exception:
            return None

    def sift(v):
        h = v.copy()
        for _ in range(4):
            u, lo = envelope(h, True), envelope(h, False)
            if u is None or lo is None:
                return None
            q = h - 0.5 * (u + lo)
            if np.max(np.abs(q - h)) <= .01 * (np.std(h) + 1e-12):
                return q
            h = q
        return h

    d = np.diff(clean)
    sd = 1.4826 * np.median(np.abs(d - np.median(d))) + 1e-12
    residual, retained = clean.copy(), []
    half_limit = max(4, int(requested_frame) // 2)

    for _ in range(3):
        mode = sift(residual)
        if mode is None:
            return _sg(clean, requested_frame)
        cross = np.flatnonzero(mode[:-1] * mode[1:] <= 0)
        amp = 1.4826 * np.median(np.abs(mode - np.median(mode)))
        half_period = np.median(np.diff(cross) * 2.0) if cross.size >= 2 else float(n)
        if not (amp < 1.35 * sd * np.sqrt(float(n)) and half_period < half_limit):
            retained.append(mode)
        residual = residual - mode
        if np.count_nonzero(np.diff(np.sign(np.diff(residual)))) < 2:
            break

    y = residual
    for mode in retained:
        y = y + mode
    return y if np.all(np.isfinite(y)) else _sg(clean, requested_frame)


def _persistent_shape(y, sigma, spread, epsilon_scale=.95):
    y = np.asarray(y, dtype=float)
    n = y.size
    if n < 3:
        return y.copy()
    eps = max(epsilon_scale * sigma, .008 * spread, 1e-12)
    chosen, queue = [0, n - 1], []

    def split(a, b):
        if b - a < 2:
            return 0., -1
        k = np.arange(a + 1, b)
        chord = y[a] + (k - a) * (y[b] - y[a]) / float(b - a)
        j = int(np.argmax(np.abs(y[k] - chord)))
        return float(np.abs(y[k][j] - chord[j])), int(k[j])

    e, k = split(0, n - 1)
    if k >= 0 and e > eps:
        queue.append((-e, 0, n - 1, k))
    while queue and len(chosen) < min(n, 98):
        queue.sort()
        _, a, b, k = queue.pop(0)
        if k in chosen:
            continue
        chosen.append(k)
        for left, right in ((a, k), (k, b)):
            e, j = split(left, right)
            if j >= 0 and e > eps:
                queue.append((-e, left, right, j))

    knots = np.array(sorted(set(chosen)), dtype=int)
    grid = np.arange(n, dtype=float)
    if knots.size < 3 or PchipInterpolator is None:
        return np.interp(grid, knots, y[knots])
    try:
        z = PchipInterpolator(knots.astype(float), y[knots])(grid)
        return z if np.all(np.isfinite(z)) else np.interp(grid, knots, y[knots])
    except Exception:
        return np.interp(grid, knots, y[knots])


def _boundaries(x, window_size):
    n = x.size
    if n < 4:
        return [0, n]
    d = np.diff(x)
    sd = 1.4826 * np.median(np.abs(d - np.median(d))) + 1e-12
    span = np.percentile(x, 95) - np.percentile(x, 5)
    threshold = max(5.0 * sd, .30 * span)
    pts = np.flatnonzero(np.abs(d) > threshold) + 1
    result = [0]
    if pts.size:
        group = [int(pts[0])]
        for p in pts[1:]:
            p = int(p)
            if p - group[-1] <= 4:
                group.append(p)
            else:
                result.append(max(group, key=lambda q: abs(d[q - 1])))
                group = [p]
        result.append(max(group, key=lambda q: abs(d[q - 1])))
    result.append(n)
    return sorted(set(result))


def _reconstruct_candidate(x, window_size, frame, eps):
    n = x.size
    span = float(np.percentile(x, 95) - np.percentile(x, 5))
    out = np.empty(n, dtype=float)
    for a, b in zip(_boundaries(x, window_size)[:-1], _boundaries(x, window_size)[1:]):
        piece = x[a:b]
        smooth = _smooth_piece(piece, frame)
        r = piece - smooth
        sig = 1.4826 * np.median(np.abs(r - np.median(r))) + 1e-12
        out[a:b] = _persistent_shape(smooth, sig, span, eps)

    om, xm = float(np.mean(out)), float(np.mean(x))
    v = float(np.mean((out - om) ** 2))
    if v > 1e-14 and np.isfinite(v):
        gain = np.clip(np.mean((out - om) * (x - xm)) / (v + 1e-12), .85, 1.20)
        out = gain * out + xm - gain * om
    else:
        out += xm - om
    return np.nan_to_num(out, nan=xm, posinf=xm, neginf=xm)


def _cost(y, endpoint):
    if y.size < 3:
        return 0.
    d = np.diff(endpoint)
    sd = 1.4826 * np.median(np.abs(d - np.median(d))) + 1e-12
    span = np.percentile(endpoint, 95) - np.percentile(endpoint, 5)
    den = max(2.5 * sd, .025 * span, 1e-10)
    s = np.sign(np.diff(y))
    nz = np.flatnonzero(s)
    if nz.size < 2:
        rev = 0
    else:
        s[:nz[0]] = s[nz[0]]
        for i in range(nz[0] + 1, s.size):
            if s[i] == 0:
                s[i] = s[i - 1]
        rev = np.count_nonzero(s[1:] != s[:-1])
    return .72 * min(np.mean(np.abs(y - endpoint)) / den, 2.) + .28 * min(rev / 50., 2.)


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1 or x.size < window_size:
        raise ValueError("window_size must be positive and not exceed signal length")
    x = _finite_signal(x)
    delay = window_size - 1
    if x.size < 5:
        return x[delay:].copy()
    endpoint = x[delay:]
    best, best_cost = None, np.inf
    for frame, eps in ((15, .78), (21, .95), (31, 1.25)):
        candidate = _reconstruct_candidate(x, window_size, frame, eps)[delay:]
        score = _cost(candidate, endpoint)
        if score < best_cost:
            best, best_cost = candidate, score
    return np.asarray(best, dtype=float)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean = (2*np.sin(np.pi*t) + 1.5*np.sin(4*np.pi*t) +
             .5*np.sin(10*np.pi*t) + .8*np.exp(-t/5)*np.sin(3*np.pi*t))
    clean += .1*t*np.sin(.2*t) + np.cumsum(rng.randn(length)*.05)
    return clean + rng.normal(0, noise_level, length), clean


def run_signal_processing(noisy_signal=None, signal_length=1000, noise_level=.3,
                          window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None
    filtered = process_signal(noisy_signal, window_size, "enhanced")
    if clean_signal is None:
        return {"filtered_signal": filtered, "clean_signal": None,
                "noisy_signal": None, "correlation": 0, "noise_reduction": 0,
                "signal_length": len(filtered)}
    d = window_size - 1
    clean, noisy = clean_signal[d:], noisy_signal[d:]
    m = min(filtered.size, clean.size)
    filtered, clean, noisy = filtered[:m], clean[:m], noisy[:m]
    corr = float(np.corrcoef(filtered, clean)[0, 1]) if m > 1 else 0.
    before, after = np.var(noisy-clean), np.var(filtered-clean)
    reduction = float((before-after)/before) if before > 0 else 0.
    return {"filtered_signal": filtered, "clean_signal": clean,
            "noisy_signal": noisy, "correlation": corr,
            "noise_reduction": reduction, "signal_length": m}


if __name__ == "__main__":
    r = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {r['correlation']:.3f}")
    print(f"Noise reduction: {r['noise_reduction']:.3f}")
    print(f"Processed signal length: {r['signal_length']}")

